const CH = { churches:null, membership:null, events:null, prayers:null, announcements:null,
             campaigns:null };

/* Giving designations. These used to be three invented campaigns baked into
   app.js with amounts already raised against a goal; a member picked one and
   then paid Stripe for real. giving_campaigns is a real table and RLS already
   allows anyone to read the active rows, so read it.

   When there are none -- a church that has not created any, or the request
   fails -- the caller falls back to a plain designation list. A designation is
   honest (the money is a tithe or an offering); a campaign with a goal bar is a
   claim about money other people have given, and we do not make that claim
   without a row behind it. */
async function loadCampaigns(churchId, force){
  if (CH.campaigns && !force) return CH.campaigns;
  /* 17 Sep: a campaign belongs to an organisation -- a church, or Chris's own
     charity once it has a row. There is no such thing as a platform-level
     campaign any more (giving_campaigns.church_id is NOT NULL), so a member
     with no church sees designations only rather than a fundraiser nobody
     is running. */
  if (!churchId) { CH.campaigns = []; return CH.campaigns; }
  CH.campaigns = await sbRest(
    "/giving_campaigns?select=id,title,description,goal_cents,raised_cents,church_id" +
    `&is_active=eq.true&church_id=eq.${encodeURIComponent(churchId)}&order=title.asc&limit=50`);
  return CH.campaigns;
}


