/* ── the state between tapped and done ────────────────────────────────────
   Every write here is a network round trip on a phone that may be on a church
   car park's worst bar of signal. Without a busy state the button looks
   untouched, so the person taps it again, and the second tap is the duplicate
   campaign. aria-busy is what a screen reader hears; .is-loading is the
   spinner; disabled is what actually stops the second tap. Always restored in
   a finally, because a button stuck spinning is worse than no spinner. */
async function withBusy(el, fn){
  if (!el) return fn();
  const wasDisabled = el.disabled;
  el.classList.add("is-loading");
  el.setAttribute("aria-busy", "true");
  el.disabled = true;
  try { return await fn(); }
  finally {
    el.classList.remove("is-loading");
    el.removeAttribute("aria-busy");
    el.disabled = wasDisabled;
  }
}

async function submitCampaign(id){
  const v = x => ((document.getElementById(x) || {}).value || "").trim();
  const title = v("cmp-title");
  if (title.length < 3) { toast("A campaign needs a title"); return; }
  const dollars = v("cmp-goal");
  const goal = dollars === "" ? 0 : Math.round(Number(dollars) * 100);
  if (!Number.isFinite(goal) || goal < 0 || goal > 100000000) { toast("Goal must be $0–$1,000,000"); return; }
  const cid = typeof myChurchId === "function" ? myChurchId() : null;
  if (!id && !cid) { toast("Join or claim your church first"); return; }
  const btn = document.getElementById("cmp-save");
  try {
    await withBusy(btn, async () => {
      if (id) await sbRpc("update_campaign", { p_campaign_id: id, p_title: title,
        p_description: v("cmp-desc"), p_goal_cents: goal, p_is_active: null });
      else await sbRpc("create_campaign", { p_church_id: cid, p_title: title,
        p_description: v("cmp-desc"), p_goal_cents: goal });
    });
    CH.campaigns = null;
    closeSheet(); toast(id ? "Campaign updated" : "Campaign created 💝"); render();
    if (typeof window.flourishHaptic === "function") window.flourishHaptic("success");
  } catch (err) {
    toast("⚠ " + err.message);
    if (typeof window.flourishHaptic === "function") window.flourishHaptic("error");
  }
}
