async function sbRest(path, opts){
  const cfg = await flourishConfig();
  if (!cfg || !cfg.supabase_url) throw new Error("Directory unavailable right now");
  const token = (typeof authToken === "function") ? await authToken() : "";
  const headers = Object.assign(
    { apikey: cfg.supabase_anon_key, "Content-Type": "application/json" },
    token ? { Authorization: "Bearer " + token } : {},
    (opts && opts.headers) || {}
  );
  // Reads get a shorter leash than writes: nobody should watch a spinner for twelve
  // seconds to be told the directory is unreachable.
  const isWrite = opts && opts.method && opts.method !== "GET";
  const r = await fetchWithTimeout(cfg.supabase_url + "/rest/v1" + path,
    Object.assign({}, opts, { headers }), isWrite ? 12000 : 7000);
  if (!r.ok) {
    const detail = await r.text().catch(() => "");
    throw new Error(sbErrorText(r.status, detail));
  }
  return r.status === 204 ? null : r.json();
}
/* PostgREST answers with JSON ({"code","message",…}). The database writes some
   of its refusals FOR people — "That email address doesn't look right.", the
   word filter's "Please rephrase." — and those end in a full stop; show them as
   they are. Anything else keeps the status code, which is what a bug report
   needs. */
function sbErrorText(status, detail){
  if (status === 401) return "Please sign in to see this";
  let msg = "";
  try { const j = JSON.parse(detail || ""); msg = (j && (j.message || j.msg || j.error)) || ""; } catch (x) {}
  msg = String(msg || "").replace(/^(TEXT_BLOCKED|PRAYER_BLOCKED):\s*/, "").trim();
  if (msg && msg.length <= 200 && /[.!?]$/.test(msg)) return msg;
  return "Could not load (" + status + ")" + (msg ? " " + msg.slice(0, 120)
    : (detail ? " " + String(detail).slice(0, 120) : ""));
}
const sbRpc = (fn, args) => sbRest("/rpc/" + fn, { method:"POST", body: JSON.stringify(args || {}) });

/* ── shared view states (items 42-44) ───────────────────────────── */
function viewLoading(what){
  /* A spinner tells a person the app is busy. A skeleton tells them what is
     coming and roughly how much of it — the wait is identical, the wait FEELS
     shorter, and the layout does not jump when the real rows land because the
     placeholder is already the right shape.

     The blocks are aria-hidden: a screen reader should hear "Loading events",
     once, from the live region, not three rows of empty divs. */
  const row = `<div class="sk-card" aria-hidden="true">
      <div class="row" style="gap:var(--sp-3);align-items:flex-start">
        <div class="sk sk-avatar"></div>
        <div style="flex:1;min-width:0">
          <div class="sk sk-line t"></div>
          <div class="sk sk-line"></div>
          <div class="sk sk-line s"></div>
        </div>
      </div>
    </div>`;
  return `<div role="status" aria-live="polite" aria-busy="true">
    <span class="sr-only">Loading ${esc(what)}…</span>
    ${row}${row}${row}
  </div>`;
}
function viewError(msg, retryFn){
  /* retryFn is a FUNCTION, registered by key. It used to be a source string
     interpolated into an onclick attribute with a server-supplied id inside a
     JS string literal -- a context esc() cannot protect (the HTML parser
     decodes the entity before JS parses the string). */
  const key = typeof retryFn === "function" ? onRetry(retryFn) : "";
  return `<div class="card" style="text-align:center;padding:26px 18px;outline:1px solid var(--line2)">
    <div style="font-size:26px">⚠️</div>
    <p style="margin:10px 0 4px"><b>That didn't load</b></p>
    <p class="muted" style="font-size:13.5px;margin:0 0 12px">${esc(msg)}</p>
    ${key ? `<button class="btn primary" data-act="retry-view" data-id="${key}">Try again</button>` : ""}</div>`;
}
function viewEmpty(icon, title, body, action){
  return `<div class="empty" style="padding:26px 18px">
    <div class="e-ic">${icon}</div><b style="display:block;margin-bottom:5px">${esc(title)}</b>
    <span class="muted" style="font-size:13.5px">${esc(body)}</span>
    ${action ? `<div style="margin-top:14px">${action}</div>` : ""}</div>`;
}
/* Mount a skeleton now, fill when the data lands. Guarded by a token so a slow
   response cannot overwrite a view the member has already navigated away from
   (item 41). */
let _viewToken = 0;
function fillView(id, producer){
  const token = ++_viewToken;
  Promise.resolve()
    .then(producer)
    .then(html => {
      if (token !== _viewToken) return;            // stale response, drop it
      const el = document.getElementById(id);
      if (el) el.innerHTML = html;
    })
    .catch(err => {
      // Without this a rejected producer leaves the skeleton spinning forever — the
      // user sees a loading state that never resolves and never explains itself.
      console.error("[flourish] view failed", err);
      if (token !== _viewToken) return;
      const el = document.getElementById(id);
      if (el) el.innerHTML = viewError(err && err.message || "Something went wrong",
                                       () => location.reload());
    });
}

