async function loadChurches(force){
  if (CH.churches && !force) return CH.churches;
  CH.churches = await sbRest("/churches?select=id,slug,name,denomination,city,state,pastor_name,service_times,logo_url,is_verified&order=name.asc&limit=100");
  return CH.churches;
}
async function loadMembership(force){
  if (CH.membership !== null && !force) return CH.membership;
  if (!(typeof isSignedIn === "function" && isSignedIn())) { CH.membership = []; return CH.membership; }
  CH.membership = await sbRest("/church_memberships?select=church_id,role,is_primary&limit=20");
  return CH.membership;
}
function myChurchId(){
  const m = CH.membership || [];
  // A super_admin seat is the PLATFORM role (is_platform_admin() is "super_admin
  // anywhere"), held in a hidden platform church — it is nobody's church.
  const real = m.filter(x => x.role !== "super_admin");
  const primary = real.find(x => x.is_primary) || real[0];
  return primary ? primary.church_id : null;
}
function isLeaderOf(id){
  return (CH.membership || []).some(m => m.church_id === id &&
    ["church_admin","pastor","super_admin"].includes(m.role));
}

